UPDATE clubs SET description = 'At MVLASD, we believe Speech and Debate (also known as “forensics”) is one of the most valuable activities a student can participate in. Participants develop research skills, strategies that will help them on standardized tests, and the ability to speak in front of large groups with poise and confidence. Students also see dramatic improvements in writing organization, clarity and concision of speech and prose, and the ability to think quickly, critically, and from multiple perspectives. Students learn to set goals, delineate the steps needed to achieve them, and then hit the ground running! Students make lifelong friends in speech and debate! High school is a critical period for developing social connections, and forensics students often say speech and debate feels like a second home to them. Please check out our website: mvlasd.club for more information.', category = 'Competition & Strategy', meeting_schedule = 'Monday, Wednesday · Weekly · After School', location = 'Library/Zoom', contact_email = '100032533@mvla.net', advisor = 'Julie Herman', status = IF(status = 'archived', 'active', status) WHERE name = 'Mountain View Los Altos Speech & Debate';
