UPDATE clubs SET description = 'MVHS Women in STEM (WiSTEM) empowers women to explore and pursue interests and careers in STEM fields, addressing the gender imbalance with a significant underrepresentation of women. In hopes of increasing the amount of women who go into STEM each year, we will provide an inclusive and supportive space for learning and mentorship that would give MVHS students the encouragement they need. Working alongside the larger Women in STEM organization, we will focus on community outreach through hands-on activities, STEM events, and guest speakers for the local youth and students of Mountain View, as well as nearby communities. Although our mission centers on uplifting women, we welcome all to join in our fun and educational meetings and be part of the process of creating a more diverse community for STEM.', category = 'Service & Leadership', meeting_schedule = 'Thursday · Biweekly · Lunch', location = 'Room P4', contact_email = '100034056@mvla.net, 100033592@mvla.net', advisor = 'Ms. Babiak', status = IF(status = 'archived', 'active', status) WHERE name = 'MVHS Women in STEM';
