UPDATE clubs SET description = 'SLAM Magazine is an organization and independent student-run publication that is dedicated to illuminating social justice issues in our community that don''t receive mainstream attention. We strive to provide insight and understand the complexities behind systems of oppression based on race, ethnicity, gender, ability, and other identities through the arts. For our team members, our organization provides career-applicable skills and experience in design, photography, media marketing, business, and writing/journalism. Students work with their teams and as an organization to produce two issues annually that get distributed throughout the MVLA community.', category = 'Service & Leadership', meeting_schedule = 'Wednesday · Weekly · After school (3:10-4:10)', location = 'Room 109', contact_email = '100032189@mvla.net', advisor = 'Lori Nock', status = IF(status = 'archived', 'active', status) WHERE name = 'SLAM Magazine';
