  SELECT 'SLAM Magazine', 'SLAM Magazine is an organization and independent student-run publication that is dedicated to illuminating social justice issues in our community that don''t receive mainstream attention. We strive to provide insight and understand the complexities behind systems of oppression based on race, ethnicity, gender, ability, and other identities through the arts. For our team members, our organization provides career-applicable skills and experience in design, photography, media marketing, business, and writing/journalism. Students work with their teams and as an organization to produce two issues annually that get distributed throughout the MVLA community.', 'Service & Leadership', 'Wednesday · Weekly · After school (3:10-4:10)', 'Room 109', '100032189@mvla.net', 'Lori Nock', 0, @school_id, 'active', 'public' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM clubs WHERE name = 'SLAM Magazine');
UPDATE clubs SET description = 'The South Asian Student Union is a club where members will learn about South Asian heritage, traditions, modern adaptations/stereotypes of South Asian Nations and also share their experiences as South Asians in America. Our club hopes to unite the South Asian community in Mountain View High School and to build self pride and confidence in their ethnicity and culture. However, we appeal to both those who identify with South Asian culture and those who wish to learn about South Asian culture.', category = 'Culture & Identity', meeting_schedule = 'Thursday · Biweekly · Lunch', location = 'Room 726', contact_email = '10031910@mvla.net', advisor = 'Felitia Hancock', status = IF(status = 'archived', 'active', status) WHERE name = 'South Asian Student Union';
