  WHERE NOT EXISTS (SELECT 1 FROM clubs WHERE name = 'South Asian Student Union');
UPDATE clubs SET description = 'Spartan Buddies at MVHS unites special needs students in our special education and Life Skills program with neurotypical MVHS students in the hopes of creating genuine friendship connections and increasing inclusivity at school. For peers with special needs, feeling different and excluded is an everyday experience. The simple action of pairing students with their Spartan Buddy and encouraging them to have genuine conversations while guiding them with fun activities can be life changing for them. It can develop intense feelings of belonging and overall joy in these students, and that is more important than we as neurotypical individuals may ever understand.', category = 'Service & Leadership', meeting_schedule = 'Thursday · Weekly · Lunch', location = 'Room 708', contact_email = '100032253@mvla.net', advisor = 'Seamus Quillinan', status = IF(status = 'archived', 'active', status) WHERE name = 'Spartan Buddies';
