  SELECT 'Spartan Buddies', 'Spartan Buddies at MVHS unites special needs students in our special education and Life Skills program with neurotypical MVHS students in the hopes of creating genuine friendship connections and increasing inclusivity at school. For peers with special needs, feeling different and excluded is an everyday experience. The simple action of pairing students with their Spartan Buddy and encouraging them to have genuine conversations while guiding them with fun activities can be life changing for them. It can develop intense feelings of belonging and overall joy in these students, and that is more important than we as neurotypical individuals may ever understand.', 'Service & Leadership', 'Thursday · Weekly · Lunch', 'Room 708', '100032253@mvla.net', 'Seamus Quillinan', 0, @school_id, 'active', 'public' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM clubs WHERE name = 'Spartan Buddies');
