UPDATE clubs SET description = 'The Pediatrics Club is a club in which participants will engage in lectures, activities, and labs concerning various areas of Pediatrics. For instance, our club will explore the fields of pediatric cardiology, pediatric neurology, and pediatric surgery. Our club would happily accept donations of synthetic dissection kits, surgical and dissection tools, children''s toys, and silicone human model pads. Our community events consist of “Adopt a teddy bear donation fair”, collecting books and toys for the children''s hospital, painting cups to donate to children''s hospitals, and hosting a children’s introduction to healthcare fair.', category = 'STEM & Innovation', meeting_schedule = 'Wednesday · Biweekly · Lunch', location = 'Room 703', contact_email = '100033684@mvla.net, 100033586@mvla.net', advisor = 'Heather Boyle', status = IF(status = 'archived', 'active', status) WHERE name = 'The Pediatrics Club';
