-- 4. Archive the clubs that dropped off the list.
UPDATE clubs
SET status = 'archived'
WHERE status = 'active'
  AND name NOT IN ('Aerospace and Aviation Club', 'AIAS Architecture Club', 'Analytics Club', 'Artificial Intelligence Club', 'Asian Pacific Union', 'Bring Change to Mind', 'Chess Club', 'Computer Science Club', 'Creative Writing Club', 'Crochet Club', 'DERM Club', 'Drama Llamas', 'Dream Volunteers Club', 'Economics Club', 'F=ma Club', 'Fellowship of Christian Athletes (FCA)', 'Fentanyl and Substance Awareness Club', 'French Club', 'French Honors Society', 'Girls Who Code Club', 'Information Security Club', 'Japanese Culture Club', 'Jewish Student Union', 'K-Pop Dance Club', 'Leo Club', 'M1820 Christian Club', 'Marine Biology and Ocean Conservation Club', 'Math Club', 'MEChA', 'Model UN', 'Mountain View High School Science Olympiad', 'Mountain View Los Altos Speech & Debate', 'Muslim Student Association (MSA)', 'MVHS BMES', 'MVHS Driver''s Association', 'MVHS Green Team', 'MVHS Jazz and Composition Club', 'MVHS Makers With A Mission', 'MVHS Red Cross Club', 'MVHS Women in STEM', 'Owed Soap', 'Psychology Club', 'Puzzle Club', 'Rock climbing club', 'SLAM Magazine', 'South Asian Student Union', 'Spartan Buddies', 'Spartan Equity Partners', 'Steam Club', 'Taiwanese American Student Association', 'TEDxMVHS', 'The Pediatrics Club', 'Theater Club', 'Ukrainian Culture Club', 'Unhoused Awareness', 'Vietnamese Student Association (VSA)', 'Women Athlete''s Club', 'Youth Hunger Initiative');

-- 5. Collapse duplicate names, keeping the lowest id. Production carried
--    two active rows named "MVHS Drivers Association", which the rename in
--    step 1 would otherwise have left as two identical directory entries.
UPDATE clubs
SET status = 'archived'
WHERE status = 'active'
  AND id NOT IN (
    SELECT keep_id FROM (
      SELECT MIN(id) AS keep_id FROM clubs WHERE status = 'active' GROUP BY name
    ) AS keepers
  );

COMMIT;
